-- Published rubric snapshots are immutable; only the active pointer can move.
-- API authentication and the operator allowlist run before these service-only RPCs.
create table public.grader_config_releases (
  id text primary key check (id ~ '^[a-zA-Z0-9_-]{1,100}$'),
  snapshot jsonb not null check (jsonb_typeof(snapshot) = 'object' and snapshot->>'id' = id and octet_length(snapshot::text) <= 250000),
  content_hash text not null check (content_hash ~ '^[a-f0-9]{64}$'),
  published_at timestamptz not null default clock_timestamp(),
  published_by uuid,
  reason text not null check (length(reason) between 10 and 500),
  parent_id text references public.grader_config_releases(id)
);
create index grader_config_releases_published_idx on public.grader_config_releases(published_at desc);
create index grader_config_releases_parent_idx on public.grader_config_releases(parent_id);
create table public.grader_config_active (
  singleton boolean primary key default true check (singleton),
  release_id text not null references public.grader_config_releases(id),
  changed_at timestamptz not null default clock_timestamp()
);
create index grader_config_active_release_idx on public.grader_config_active(release_id);
create table public.grader_config_audit (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid,
  action text not null check (action in ('seed','publish','rollback')),
  from_id text references public.grader_config_releases(id),
  to_id text not null references public.grader_config_releases(id),
  reason text not null check (length(reason) between 10 and 500),
  created_at timestamptz not null default clock_timestamp()
);
create index grader_config_audit_from_idx on public.grader_config_audit(from_id);
create index grader_config_audit_to_idx on public.grader_config_audit(to_id);
alter table public.grader_config_releases enable row level security;
alter table public.grader_config_active enable row level security;
alter table public.grader_config_audit enable row level security;
revoke all on public.grader_config_releases, public.grader_config_active, public.grader_config_audit from public, anon, authenticated;
grant select, insert on public.grader_config_releases, public.grader_config_audit to service_role;
grant select, insert, update on public.grader_config_active to service_role;

create function public.grader_config_block_mutation()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  raise exception using errcode = '55000', message = 'published_configuration_is_immutable';
end;
$$;
create trigger grader_config_release_immutable before update or delete on public.grader_config_releases for each row execute function public.grader_config_block_mutation();
create trigger grader_config_audit_immutable before update or delete on public.grader_config_audit for each row execute function public.grader_config_block_mutation();

create function public.grader_config_read_release(p_id text)
returns jsonb language sql stable security invoker set search_path = '' as $$
  select jsonb_build_object('release',r.snapshot,'contentHash',r.content_hash,'publishedAt',r.published_at,'reason',r.reason,'parentId',r.parent_id)
    from public.grader_config_releases r where r.id = p_id;
$$;
create function public.grader_config_read_active()
returns jsonb language sql stable security invoker set search_path = '' as $$
  select public.grader_config_read_release(a.release_id) from public.grader_config_active a where a.singleton;
$$;
create function public.grader_config_list_releases()
returns jsonb language sql stable security invoker set search_path = '' as $$
  select coalesce(jsonb_agg(r.payload order by r.published_at desc),'[]'::jsonb) from (
    select public.grader_config_read_release(id) payload, published_at from public.grader_config_releases order by published_at desc limit 100
  ) r;
$$;
create function public.grader_config_publish(p_snapshot jsonb, p_hash text, p_expected_id text, p_reason text, p_actor uuid)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_current text; v_id text;
begin
  if p_actor is null or p_reason is null or length(btrim(p_reason)) not between 10 and 500 or p_expected_id is null then
    raise exception using errcode = '22023', message = 'invalid_configuration_change';
  end if;
  if p_snapshot is null or jsonb_typeof(p_snapshot) is distinct from 'object' or p_snapshot->>'status' is distinct from 'approved' or p_snapshot->>'provisional' is distinct from 'true' or jsonb_typeof(p_snapshot->'minCoverage') is distinct from 'number' then
    raise exception using errcode = '22023', message = 'invalid_configuration_snapshot';
  end if;
  if (p_snapshot->>'minCoverage')::numeric not between 0.8 and 1 then
    raise exception using errcode = '22023', message = 'invalid_configuration_coverage';
  end if;
  v_id := p_snapshot->>'id';
  if v_id is null or v_id !~ '^config-[a-f0-9-]{36}$' or p_hash is null or p_hash !~ '^[a-f0-9]{64}$' then
    raise exception using errcode = '22023', message = 'invalid_configuration_identity';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('grader_config_active',0));
  select release_id into v_current from public.grader_config_active where singleton;
  if v_current is distinct from p_expected_id then return jsonb_build_object('conflict',true); end if;
  insert into public.grader_config_releases(id,snapshot,content_hash,published_by,reason,parent_id)
    values(v_id,p_snapshot,p_hash,p_actor,btrim(p_reason),v_current);
  update public.grader_config_active set release_id = v_id, changed_at = clock_timestamp() where singleton;
  insert into public.grader_config_audit(actor_id,action,from_id,to_id,reason) values(p_actor,'publish',v_current,v_id,btrim(p_reason));
  return public.grader_config_read_release(v_id);
end;
$$;
create function public.grader_config_rollback(p_id text, p_expected_id text, p_reason text, p_actor uuid)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_current text;
begin
  if p_actor is null or p_reason is null or length(btrim(p_reason)) not between 10 and 500 or p_expected_id is null then
    raise exception using errcode = '22023', message = 'invalid_configuration_change';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('grader_config_active',0));
  select release_id into v_current from public.grader_config_active where singleton;
  if v_current is distinct from p_expected_id then return jsonb_build_object('conflict',true); end if;
  if not exists(select 1 from public.grader_config_releases where id = p_id) then return jsonb_build_object('missing',true); end if;
  update public.grader_config_active set release_id = p_id, changed_at = clock_timestamp() where singleton;
  insert into public.grader_config_audit(actor_id,action,from_id,to_id,reason) values(p_actor,'rollback',v_current,p_id,btrim(p_reason));
  return public.grader_config_read_release(p_id);
end;
$$;
revoke all on function public.grader_config_block_mutation(), public.grader_config_read_release(text), public.grader_config_read_active(), public.grader_config_list_releases(), public.grader_config_publish(jsonb,text,text,text,uuid), public.grader_config_rollback(text,text,text,uuid) from public, anon, authenticated;
grant execute on function public.grader_config_read_release(text), public.grader_config_read_active(), public.grader_config_list_releases(), public.grader_config_publish(jsonb,text,text,text,uuid), public.grader_config_rollback(text,text,text,uuid) to service_role;

